/* Lot 93: sin, cos, tan, asin, acos, atan and atan2 simplified (generated by scripts/lot93_mathgen.py; expectations from lot93_mathmodel.py). */

#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[64], g_r[96];

static const char *ev(const char *v) {
    int t = -1, r = wf_cssprop_math_eval(v, &t, g_o, (int)sizeof(g_o));
    if (r < 0) return t == 0 && !g_o[0] ? "BAD" : "BAD BUT SET";
    if (r == 0) snprintf(g_r, sizeof(g_r), "T%d %s", t, g_o[0] ? "WRITTEN" : "KEEP");
    else snprintf(g_r, sizeof(g_r), "T%d %s", t, g_o);
    return g_r;
}

static void test_l93_trig_0(void) {
    TEST_ASSERT_EQUAL_STRING("T5 KEEP", ev("COS( 102.5848)"));
    TEST_ASSERT_EQUAL_STRING("T5 1", ev("cos(0.55736GRAD)"));
    TEST_ASSERT_EQUAL_STRING("T8 KEEP", ev("aTan2(\t143152.7,\t-20.596 )"));
    TEST_ASSERT_EQUAL_STRING("T5 -0.291", ev("tan(\t6  )"));
    TEST_ASSERT_EQUAL_STRING("T8 KEEP", ev("atan2(4.03460px,-144697.44625px  )"));
    TEST_ASSERT_EQUAL_STRING("T8 -42.6141deg", ev("ATAN(-0.92 )"));
    TEST_ASSERT_EQUAL_STRING("T5 -0.1874", ev("SIN(\t-3.030turn)"));
    TEST_ASSERT_EQUAL_STRING("T5 -0.4161", ev("cos(-2)"));
}

